"""Billing's retry contract (RC seed) — consumed by Orders' dispatch."""

RETRY_POLICY = {"base_seconds": 2, "max_attempts": 5, "jitter": "full", "version": "v2"}


def describe_policy() -> str:
    return f"retry policy {RETRY_POLICY['version']} base={RETRY_POLICY['base_seconds']}s"
